import org.eclipse.rdf4j.common.iteration.CloseableIteratorIteration;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.estimation.LmdbQuadSynopsisService;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class SketchBasedJoinEstimatorInaccessibleMarkerTest {

	@Test
	void languageMigrationCannotIgnoreAnInaccessibleSynopsisDirectory(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Assumptions.assumeTrue(Files.getFileAttributeView(evidence, PosixFileAttributeView.class) != null,
				"POSIX permissions are unavailable");
		Path parent = Files.createDirectory(evidence.resolve("restricted-parent"));
		Path directory = parent.resolve("synopsis");
		var vf = SimpleValueFactory.getInstance();
		var row = vf.createStatement(vf.createIRI("urn:inaccessible:s"), vf.createIRI("urn:inaccessible:p"),
				vf.createLiteral(1));
		try (SketchBasedJoinEstimator estimator = new SketchBasedJoinEstimator(
				(s, p, o, c) -> new CloseableIteratorIteration<>(List.of(row).iterator()),
				SketchBasedJoinEstimator.Config.defaults().withMemoryBudgetBytes(4L * 1024L * 1024L))) {
			estimator.configurePersistence(directory, false);
			estimator.rebuild();
			estimator.persistIfDirty();
		}
		Path snapshot = directory.resolve("synopsis-v8.bin");
		Path backup = evidence.resolve("original-v8-backup.bin");
		Files.copy(snapshot, backup);
		var permissions = Files.getPosixFilePermissions(parent);
		try {
			Files.setPosixFilePermissions(parent, Set.of());
			Assumptions.assumeFalse(Files.isDirectory(directory), "test user can still traverse the restricted parent");
			assertThrows(IOException.class, () -> LmdbQuadSynopsisService.markRebuildRequired(directory),
					"the migration must stop when it cannot fence a potentially existing synopsis");
		} finally {
			Files.setPosixFilePermissions(parent, permissions);
		}
		assertTrue(Files.isRegularFile(snapshot));
		assertEquals(-1L, Files.mismatch(snapshot, backup));
		assertFalse(Files.exists(directory.resolve("synopsis-v8.rebuild")));
	}
}
